INSERT INTO detail_code (
  detail_code_id, group_id, code_value, code_name, parent_detail_code_id, display_order, additional_attributes, use_yn
) VALUES (
  #{detailCodeId}, #{groupId}, #{request.codeValue}, #{request.codeName},
  NULLIF(#{request.parentDetailCodeId}, ''), #{request.displayOrder}, CAST(#{additionalAttributes} AS jsonb), #{useYn}
)

INSERT INTO change_history (
  change_history_id, entity_name, entity_id, before_value, after_value, actor_user_id, changed_at, reason, status
) VALUES (
  #{changeHistoryId}, #{entityName}, #{entityId}, CAST(#{beforeValue} AS jsonb), CAST(#{afterValue} AS jsonb),
  #{actorUserId}, current_timestamp, #{reason}, 'RECORDED'
)
